#include "preview_panel_model.h"
#include "document.h"
#include <iostream>
#include <stdexcept>
using namespace moon;
static void check(bool yes,const char* why){if(!yes)throw std::runtime_error(why);}
int main(){try{preview::View view;check(!view.zoom&&view.pan.x==0&&!view.follow,"Preview defaults");const auto fit=view.scale(2,2,201,201,1);check(fit==100,"Pixel-aligned initial fit");check(view.scale(2,2,400,400)==fit,"Resize retains initial fit");view.setZoom(2,2,400,400,40,{80,90});check(view.zoom==40,"Absolute preview zoom");const auto before=view.origin(2,2,fit,{}),after=view.origin(2,2,40,view.pan);check(std::abs((80-before.x)/fit-(80-after.x)/40)<.02,"Pointer anchor retained");check(referenceFit(.25,2)==.25,"Preview downscale is not cropped");Document doc(2,2);doc.addFrame();doc.addFrame();const auto frame=doc.frame().id;const auto history=doc.historySize();preview::Playback p;p.frame=frame;p.mode="once";p.setPlaying(doc.timeline().state(),true);check(p.frame==doc.timeline().state().frames.front().id,"Once starts at first playable");p.step(doc.timeline().state());check(p.frame==doc.timeline().state().frames[1].id,"Independent frame progression");p.returnToStart=true;p.stop();check(p.frame==frame,"Preview return to start");check(doc.frame().id==frame&&doc.historySize()==history,"Preview preserves main frame/history");p.frame=frame;p.mode="all";p.setPlaying(doc.timeline().state(),true);p.step(doc.timeline().state());check(p.frame==doc.timeline().state().frames.front().id,"All wraps frames");std::cout<<"preview panel passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
